export function projectCoord([lng, lat]: [number, number]): [number, number] {
  if (lng < -12 && lat < 31) {
    const x = 45.1 + (lng - (-18.25)) * 0.878609 * 44.1026;
    const y = 456 + (29.5 - lat) * 44.1026;
    return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
  }
  const x = 230.1 + (lng - (-9.4)) * 0.771625 * 57.2727;
  const y = 38 + (43.9 - lat) * 57.2727;
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}
